const http2 = require('node:http2')
const { H2CClient } = require('./index.js')

process.on('uncaughtException', (err) => {
  console.log('[UNCAUGHT]', err.stack)
  process.exit(1)
})

const scenario = process.argv[2] || 'abort-headers'

const sockets = []
const server = http2.createServer()
server.on('connection', (s) => sockets.push(s))
server.on('stream', (stream, headers) => {
  if (scenario === 'abort-body' || scenario === 'abort-body-goaway') {
    stream.respond({ ':status': 200, 'content-length': '100' })
    stream.write('partial')
  }
  // otherwise never respond
})

server.listen(0, async () => {
  const port = server.address().port
  const client = new H2CClient('http://localhost:' + port)
  const ac = new AbortController()
  client.request({ path: '/', method: 'GET', signal: ac.signal })
    .then(({ body }) => {
      console.log('resolved')
      body.on('error', (e) => console.log('body error:', e.message))
      body.resume()
    })
    .catch((e) => console.log('request rejected:', e.name, e.message))

  setTimeout(() => {
    console.log('aborting')
    ac.abort()
  }, 200)
  setTimeout(() => {
    if (scenario === 'abort-body-goaway') {
      console.log('server goaway + end')
      for (const s of sockets) {
        s[Object.getOwnPropertySymbols(s).find(sym => sym.toString().includes('session'))]
      }
    }
    console.log('server half-closing socket')
    for (const s of sockets) s.end()
  }, 400)
  setTimeout(() => {
    console.log('no uncaught exception')
    process.exit(0)
  }, 1500)
})

