'use strict'
const { createSecureServer } = require('node:http2')
const pem = require('@metcoder95/https-pem')
const { Agent, request, interceptors } = require('./index.js')

process.on('uncaughtException', (err) => {
  console.log('[UNCAUGHT]', err.stack)
  process.exit(1)
})

const server = createSecureServer({ ...pem })
const sessions = new Set()

server.on('session', (s) => {
  sessions.add(s)
  s.on('close', () => sessions.delete(s))
  s.on('error', () => {})
})

let n = 0
server.on('stream', (stream, headers) => {
  stream.on('error', () => {})
  const mode = (n++) % 4
  if (mode === 0) {
    // stall before headers
  } else if (mode === 1) {
    stream.respond({ ':status': 200, 'content-length': '1000000' })
    stream.write(Buffer.alloc(2048))
  } else if (mode === 2) {
    stream.respond({ ':status': 200 })
    stream.end('ok')
  } else {
    // graceful goaway then FIN a bit later
    stream.respond({ ':status': 200, 'content-length': '1000000' })
    stream.write(Buffer.alloc(2048))
    const session = stream.session
    setTimeout(() => {
      if (session && !session.destroyed) {
        session.goaway()
        setTimeout(() => session.socket?.end(), 30)
      }
    }, 25)
  }
})

server.listen(0, async () => {
  const port = server.address().port
  const dispatcher = new Agent({ connect: { rejectUnauthorized: false }, allowH2: true })
    .compose(interceptors.redirect({ maxRedirections: 5 }))

  const url = `https://localhost:${port}/file`

  for (let round = 0; round < 60; round++) {
    const reqs = []
    for (let i = 0; i < 6; i++) {
      reqs.push(request(url, { dispatcher, signal: AbortSignal.timeout(10 + ((round + i) % 7) * 7) })
        .then(({ statusCode, body }) => {
          if (statusCode >= 200 && statusCode < 300 && (round + i) % 2 === 0) {
            body.on('error', () => {})
            body.resume()
            return
          }
          return body.dump().catch(() => {})
        })
        .catch(() => {}))
    }
    await Promise.all(reqs)
    // let the server's delayed goaway/FIN land on an idle client
    await new Promise(resolve => setTimeout(resolve, 40))
  }

  await new Promise(resolve => setTimeout(resolve, 500))
  console.log('no uncaught exception')
  process.exit(0)
})

