'use strict'
const { createSecureServer } = require('node:http2')
const pem = require('@metcoder95/https-pem')
const { Agent, request, interceptors } = require('./index.js')

process.on('uncaughtException', (err) => {
  console.log('[UNCAUGHT]', err.stack)
  process.exit(1)
})

const mode = process.argv[2] || 'fin-midbody'

const server = createSecureServer({ ...pem })
const rawSockets = new Set()
server.on('secureConnection', (s) => {
  rawSockets.add(s)
  s.on('close', () => rawSockets.delete(s))
  s.on('error', () => {})
})
server.on('session', (s) => s.on('error', () => {}))

server.on('stream', (stream, headers) => {
  stream.on('error', () => {})
  stream.respond({ ':status': 200, 'content-length': '10000000' })
  stream.write(Buffer.alloc(4096))
  // FIN the TCP connection mid-body
  setTimeout(() => {
    for (const s of rawSockets) s.end()
  }, 60)
})

server.listen(0, async () => {
  const port = server.address().port
  const dispatcher = new Agent({ connect: { rejectUnauthorized: false }, allowH2: true })
    .compose(interceptors.redirect({ maxRedirections: 5 }))
  const url = `https://localhost:${port}/file`

  for (let round = 0; round < 25; round++) {
    const reqs = []
    for (let i = 0; i < 4; i++) {
      const opts = { dispatcher }
      if (mode === 'abort') opts.signal = AbortSignal.timeout(50 + i * 5)
      reqs.push(request(url, opts)
        .then(({ body }) => {
          body.on('error', () => {})
          if (mode === 'slow') {
            body.on('data', () => {})
            body.pause()
            return new Promise(resolve => { body.on('close', resolve); setTimeout(resolve, 300) })
          }
          body.resume()
          return new Promise(resolve => body.on('close', resolve))
        })
        .catch(() => {}))
    }
    await Promise.all(reqs)
    await new Promise(resolve => setTimeout(resolve, 10))
  }
  await new Promise(resolve => setTimeout(resolve, 300))
  console.log('no uncaught exception')
  process.exit(0)
})

